#!/bin/bash
# ╔══════════════════════════════════════════════╗
# ║   SparrowShield Agent — macOS Installer      ║
# ║   No admin / sudo required. Self-contained.  ║
# ║   Run: bash SparrowShield-Mac-Install.sh     ║
# ╚══════════════════════════════════════════════╝

set -e

INSTALL_DIR="$HOME/.sparrow-agent"
CONFIG="$INSTALL_DIR/config.json"
AGENT="$INSTALL_DIR/agent_mac.py"
LOG="$INSTALL_DIR/agent.log"
PLIST="$HOME/Library/LaunchAgents/com.sparrowshield.agent.plist"

RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'
CYAN='\033[0;36m'; WHITE='\033[1;37m'; RESET='\033[0m'

echo ""
echo -e "${CYAN}  ╔══════════════════════════════════════════════╗${RESET}"
echo -e "${CYAN}  ║   SparrowShield Agent — macOS Installer      ║${RESET}"
echo -e "${CYAN}  ╚══════════════════════════════════════════════╝${RESET}"
echo ""

# Step 1
echo -e "${WHITE}  [1/5] Creating install directory...${RESET}"
mkdir -p "$INSTALL_DIR"
echo -e "${GREEN}         $INSTALL_DIR${RESET}"

# Step 2
echo -e "${WHITE}  [2/5] Writing config...${RESET}"
cat > "$CONFIG" << 'CONFJSON'
{
  "api_url": "https://hevcfhxmjgbpozqtescm.supabase.co/functions/v1",
  "anon_key": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImhldmNmaHhtamdicG96cXRlc2NtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzEyMjk4NDYsImV4cCI6MjA4NjgwNTg0Nn0.CaXbG8F54bXV0_biNka7vp6Cl1s7vvQsRogNoz7jB28",
  "device_id": "",
  "device_token": ""
}
CONFJSON
echo -e "${GREEN}         config.json written.${RESET}"

# Step 3
echo -e "${WHITE}  [3/5] Writing agent...${RESET}"
AGENT_B64=""
echo "$AGENT_B64" | base64 -d > "$AGENT"
echo -e "${GREEN}         agent_mac.py written ($(wc -l < "$AGENT") lines).${RESET}"

# Step 4: Find Python — check PATH and known hardcoded locations
echo -e "${WHITE}  [4/5] Installing Python dependencies...${RESET}"

PYTHON=""
for cmd in     python3 python3.14 python3.13 python3.12 python3.11 python3.10 python3.9 python3.8     /opt/homebrew/bin/python3 /opt/homebrew/bin/python3.14 /opt/homebrew/bin/python3.13     /opt/homebrew/bin/python3.12 /opt/homebrew/bin/python3.11 /opt/homebrew/bin/python3.10     /usr/bin/python3 /usr/local/bin/python3     /Library/Frameworks/Python.framework/Versions/Current/bin/python3; do
    if command -v "$cmd" &>/dev/null || [ -x "$cmd" ]; then
        VER="$("$cmd" -c "import sys; print(sys.version_info >= (3,8))" 2>/dev/null)"
        if [ "$VER" = "True" ]; then
            PYTHON="$cmd"
            break
        fi
    fi
done

if [ -z "$PYTHON" ]; then
    echo -e "${RED}  ERROR: Python 3.8+ not found.${RESET}"
    echo ""
    echo -e "${YELLOW}  Install Python 3 with one of these:${RESET}"
    echo -e "${WHITE}    brew install python3${RESET}"
    echo -e "${WHITE}    — or download from https://python.org${RESET}"
    exit 1
fi

echo -e "${GREEN}         Using: $PYTHON ($("$PYTHON" --version 2>&1))${RESET}"

"$PYTHON" -m pip install --quiet psutil requests 2>/dev/null || "$PYTHON" -m pip install --quiet --break-system-packages psutil requests 2>/dev/null || "$PYTHON" -m pip install --user --quiet psutil requests 2>/dev/null || true

if ! "$PYTHON" -c "import psutil, requests" 2>/dev/null; then
    echo -e "${RED}  ERROR: Could not import psutil/requests.${RESET}"
    echo -e "${YELLOW}  Try: $PYTHON -m pip install psutil requests${RESET}"
    exit 1
fi
echo -e "${GREEN}         psutil + requests ready.${RESET}"

# Step 5
echo -e "${WHITE}  [5/5] Registering auto-start...${RESET}"

PYTHON_PATH="$(command -v "$PYTHON" 2>/dev/null || echo "$PYTHON")"

if [ -f "$PLIST" ]; then
    launchctl bootout "gui/$(id -u)" "$PLIST" 2>/dev/null ||     launchctl unload "$PLIST" 2>/dev/null || true
    sleep 1
fi

cat > "$PLIST" << PLISTEOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>com.sparrowshield.agent</string>
    <key>ProgramArguments</key>
    <array>
        <string>${PYTHON_PATH}</string>
        <string>${AGENT}</string>
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
    <key>StandardOutPath</key>
    <string>${LOG}</string>
    <key>StandardErrorPath</key>
    <string>${LOG}</string>
    <key>WorkingDirectory</key>
    <string>${INSTALL_DIR}</string>
</dict>
</plist>
PLISTEOF

launchctl bootstrap "gui/$(id -u)" "$PLIST" 2>/dev/null || launchctl load -w "$PLIST" 2>/dev/null || true

echo -e "${GREEN}         LaunchAgent registered.${RESET}"

echo ""
echo -e "${WHITE}  Waiting for enrollment...${RESET}"
sleep 6

if [ -f "$LOG" ]; then
    echo ""
    echo -e "${CYAN}  Agent log:${RESET}"
    tail -15 "$LOG" | while IFS= read -r line; do
        echo -e "${WHITE}    $line${RESET}"
    done
else
    echo -e "${YELLOW}  Log not yet created — agent still starting.${RESET}"
    echo -e "${YELLOW}  Check: tail -f $LOG${RESET}"
fi

echo ""
echo -e "${CYAN}  ╔══════════════════════════════════════════════╗${RESET}"
echo -e "${GREEN}  ║  Done! Device will appear in dashboard now.  ║${RESET}"
echo -e "${CYAN}  ╠══════════════════════════════════════════════╣${RESET}"
echo -e "${WHITE}  ║  Install : $INSTALL_DIR${RESET}"
echo -e "${WHITE}  ║  Log     : $LOG${RESET}"
echo -e "${WHITE}  ║  Config  : $CONFIG${RESET}"
echo -e "${CYAN}  ╚══════════════════════════════════════════════╝${RESET}"
echo ""
echo -e "  Live log : ${YELLOW}tail -f $LOG${RESET}"
echo -e "  Uninstall: ${YELLOW}launchctl bootout gui/$(id -u) $PLIST && rm -rf $INSTALL_DIR $PLIST${RESET}"
echo ""
